import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused Linear + Sum Reduction
fused_linear_sum_cpp = "torch::Tensor fused_linear_sum_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias);"
fused_linear_sum_cuda = """
#include <torch/extension.h>
#include <cuda.h>

__global__ void fused_linear_sum_kernel(
    const float* x, const float* weight_sum, float bias_sum,
    float* out, int batch_size, int in_features
) {
    const int row = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < batch_size) {
        float val = 0.0f;
        for(int col=0; col<in_features; ++col) {
            val += x[row*in_features + col] * weight_sum[col];
        }
        out[row] = val + bias_sum;
    }
}

torch::Tensor fused_linear_sum_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    auto weight_sum = torch::sum(weight, 0);
    auto bias_sum = torch::sum(bias);
    auto out = torch::empty({x.size(0), 1}, x.options());

    const int batch_size = x.size(0);
    const int in_features = x.size(1);
    const int block_size = 256;
    const int grid_size = (batch_size + block_size - 1) / block_size;

    fused_linear_sum_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        weight_sum.data_ptr<float>(),
        bias_sum.item<float>(),
        out.data_ptr<float>(),
        batch_size,
        in_features
    );

    return out;
}
"""

# Post-ops Fusion
post_ops_cpp = "torch::Tensor post_ops_cuda(torch::Tensor x);"
post_ops_cuda = """
#include <torch/extension.h>

__global__ void post_ops_kernel(const float* input, float* output, int numel) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < numel) {
        output[idx] = input[idx];
    }
}

torch::Tensor post_ops_cuda(torch::Tensor x) {
    auto out = torch::empty_like(x);
    const int numel = x.numel();
    const int block_size = 256;
    const int grid_size = (numel + block_size - 1) / block_size;

    post_ops_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        numel
    );
    return out;
}
"""

# Load kernels
fused_linear_sum_ext = load_inline(
    name='fused_linear_sum',
    cpp_sources=fused_linear_sum_cpp,
    cuda_sources=fused_linear_sum_cuda,
    functions=['fused_linear_sum_cuda'],
    verbose=False
)

post_ops_ext = load_inline(
    name='post_ops',
    cpp_sources=post_ops_cpp,
    cuda_sources=post_ops_cuda,
    functions=['post_ops_cuda'],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
        bound = 1 / (fan_in**0.5) if fan_in > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        x = fused_linear_sum_ext.fused_linear_sum_cuda(x, self.weight, self.bias)
        x = post_ops_ext.post_ops_cuda(x)
        return x
